package matsyir.pvpperformancetracker.controllers;

import java.util.ArrayList;
import matsyir.pvpperformancetracker.models.FightLogEntry;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class FightPerformanceRelativeTickTest
{
	@Test
	public void makeLogTicksRelativeToFightStartUsesEarliestLogTickFallback()
	{
		ArrayList<FightLogEntry> logs = new ArrayList<>();
		int[] attackerGear = {1, 2, 3};
		int[] defenderGear = {4, 5, 6};

		FightLogEntry first = new FightLogEntry(attackerGear, 21, 0.5, 1, 12, defenderGear, "competitor", 100, 1000L);
		FightLogEntry second = new FightLogEntry(attackerGear, 21, 0.5, 1, 12, defenderGear, "opponent", 106, 4600L);
		logs.add(first);
		logs.add(second);

		FightPerformance.makeLogTicksRelativeToStart(logs, 100);

		assertEquals(0, first.getTick());
		assertEquals(6, second.getTick());
	}
}

package matsyir.pvpperformancetracker.controllers;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class FightPerformancePvpHubSyncTest
{
	@Test
	public void syncedFightIsReorientedToLocalPlayerPerspective()
	{
		FightPerformance localFight = fight("Player A", "Player B", 10, 20);
		FightPerformance syncedFight = fight("Player B", "Player A", 200, 100);

		localFight.setPvpHubSyncedFight(syncedFight);

		FightPerformance displayFight = localFight.getPvpHubDisplayFight();
		assertEquals("Player A", displayFight.getCompetitor().getName());
		assertEquals(100, displayFight.getCompetitor().getDamageDealt());
		assertEquals("Player B", displayFight.getOpponent().getName());
		assertEquals(200, displayFight.getOpponent().getDamageDealt());
	}

	@Test
	public void syncedFightKeepsMatchingLocalPlayerPerspective()
	{
		FightPerformance localFight = fight("Player A", "Player B", 10, 20);
		FightPerformance syncedFight = fight("Player A", "Player B", 100, 200);

		localFight.setPvpHubSyncedFight(syncedFight);

		FightPerformance displayFight = localFight.getPvpHubDisplayFight();
		assertEquals("Player A", displayFight.getCompetitor().getName());
		assertEquals(100, displayFight.getCompetitor().getDamageDealt());
		assertEquals("Player B", displayFight.getOpponent().getName());
		assertEquals(200, displayFight.getOpponent().getDamageDealt());
	}

	@Test
	public void syncedFightCanReorientWhenOnlyOpponentNameMatches()
	{
		FightPerformance localFight = fight("Player A", "Player B", 10, 20);
		FightPerformance syncedFight = fight("Player B", "Hidden-12345", 200, 100);

		localFight.setPvpHubSyncedFight(syncedFight);

		FightPerformance displayFight = localFight.getPvpHubDisplayFight();
		assertEquals("Player A", displayFight.getCompetitor().getName());
		assertEquals(100, displayFight.getCompetitor().getDamageDealt());
		assertEquals("Player B", displayFight.getOpponent().getName());
		assertEquals(200, displayFight.getOpponent().getDamageDealt());
	}

	@Test
	public void syncedFightCanReorientWithStoredHiddenUploadName()
	{
		FightPerformance localFight = fight("Player A", "Player B", 10, 20);
		localFight.recordPvpHubUploadName("Hidden-11111");
		FightPerformance syncedFight = fight("Hidden-22222", "Hidden-11111", 200, 100);

		localFight.setPvpHubSyncedFight(syncedFight);

		FightPerformance displayFight = localFight.getPvpHubDisplayFight();
		assertEquals("Player A", displayFight.getCompetitor().getName());
		assertEquals(100, displayFight.getCompetitor().getDamageDealt());
		assertEquals("Player B", displayFight.getOpponent().getName());
		assertEquals(200, displayFight.getOpponent().getDamageDealt());
	}

	@Test
	public void syncedFightFallsBackToStatsWhenNamesCannotOrient()
	{
		FightPerformance localFight = fight("Player A", "Player B", 10, 80);
		FightPerformance syncedFight = fight("Hidden-22222", "Hidden-11111", 80, 10);

		localFight.setPvpHubSyncedFight(syncedFight);

		FightPerformance displayFight = localFight.getPvpHubDisplayFight();
		assertEquals("Player A", displayFight.getCompetitor().getName());
		assertEquals(10, displayFight.getCompetitor().getDamageDealt());
		assertEquals("Player B", displayFight.getOpponent().getName());
		assertEquals(80, displayFight.getOpponent().getDamageDealt());
	}

	@Test
	public void syncedFightDoesNotUseAmbiguousStatsToSwap()
	{
		FightPerformance localFight = fight("Player A", "Player B", 50, 50);
		FightPerformance syncedFight = fight("Hidden-22222", "Hidden-11111", 50, 50);

		localFight.setPvpHubSyncedFight(syncedFight);

		FightPerformance displayFight = localFight.getPvpHubDisplayFight();
		assertEquals("Player A", displayFight.getCompetitor().getName());
		assertEquals(50, displayFight.getCompetitor().getDamageDealt());
		assertEquals("Player B", displayFight.getOpponent().getName());
		assertEquals(50, displayFight.getOpponent().getDamageDealt());
	}

	private static FightPerformance fight(String competitorName, String opponentName, int competitorDamage, int opponentDamage)
	{
		FightPerformance fight = new FightPerformance();
		fight.competitor = fighter(competitorName, competitorDamage);
		fight.opponent = fighter(opponentName, opponentDamage);
		return fight;
	}

	private static Fighter fighter(String name, int damage)
	{
		Fighter fighter = new Fighter(name);
		fighter.addAttacks(1, 1, damage, damage, 0, 0, 0, 0, 0, 0, 0);
		return fighter;
	}
}

package matsyir.pvpperformancetracker.controllers;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import matsyir.pvpperformancetracker.models.AnimationData;
import matsyir.pvpperformancetracker.models.EquipmentData;
import matsyir.pvpperformancetracker.models.RangeAmmoData;
import net.runelite.api.SpriteID;
import org.junit.Test;
import sun.misc.Unsafe;

import static org.junit.Assert.assertEquals;

public class PvpDamageCalcMagicPrayerTest
{
	@Test
	public void auguryAndVirtusAncientBonusProduceFortyIceBarrageMaxHit() throws Exception
	{
		PvpDamageCalc calc = newCalc();

		Method getMagicMaxHit = PvpDamageCalc.class.getDeclaredMethod(
			"getMagicMaxHit",
			int.class,
			AnimationData.class,
			int.class,
			EquipmentData.VoidStyle.class,
			EquipmentData.class,
			EquipmentData.class,
			EquipmentData.class,
			EquipmentData.class,
			EquipmentData.class);
		getMagicMaxHit.setAccessible(true);

		getMagicMaxHit.invoke(
			calc,
			25,
			AnimationData.MAGIC_ANCIENT_MULTI_TARGET,
			SpriteID.PRAYER_AUGURY,
			EquipmentData.VoidStyle.NONE,
			null,
			EquipmentData.ZURIELS_STAFF,
			null,
			EquipmentData.VIRTUS_ROBE_TOP,
			EquipmentData.VIRTUS_ROBE_BOTTOM);

		assertEquals(40, calc.getMaxHit());
	}

	@Test
	public void protectionPrayerReducesExpectedDamageButNotDisplayedMaxHit() throws Exception
	{
		PvpDamageCalc calc = newCalc();
		setField(calc, "maxHit", 40);
		setField(calc, "minHit", 0);
		setField(calc, "accuracy", 1.0);

		Method getAverageHit = PvpDamageCalc.class.getDeclaredMethod(
			"getAverageHit",
			boolean.class,
			EquipmentData.class,
			boolean.class);
		getAverageHit.setAccessible(true);

		getAverageHit.invoke(calc, false, EquipmentData.ZURIELS_STAFF, false);

		assertEquals(12.0, calc.getAverageHit(), 0.0001);
		assertEquals(40, calc.getMaxHit());
		assertEquals(0, calc.getMinHit());
	}

	@Test
	public void thrownJavelinDoesNotUseEquippedBoltsAsAmmo() throws Exception
	{
		PvpDamageCalc calc = newCalc();
		setField(calc, "isLmsFight", false);

		Method getWeaponAmmo = PvpDamageCalc.class.getDeclaredMethod(
			"getWeaponAmmo",
			EquipmentData.class,
			Integer.class);
		getWeaponAmmo.setAccessible(true);

		RangeAmmoData ammo = (RangeAmmoData) getWeaponAmmo.invoke(
			calc,
			EquipmentData.MORRIGANS_JAVELIN,
			RangeAmmoData.StrongBoltAmmo.OPAL_DRAGON_BOLTS_E.getItemId());

		assertEquals(null, ammo);
	}

	@Test
	public void bowCanUseCompatibleEquippedArrows() throws Exception
	{
		PvpDamageCalc calc = newCalc();
		setField(calc, "isLmsFight", false);

		Method getWeaponAmmo = PvpDamageCalc.class.getDeclaredMethod(
			"getWeaponAmmo",
			EquipmentData.class,
			Integer.class);
		getWeaponAmmo.setAccessible(true);

		RangeAmmoData ammo = (RangeAmmoData) getWeaponAmmo.invoke(
			calc,
			EquipmentData.MAGIC_SHORTBOW,
			RangeAmmoData.OtherAmmo.SEEKING_DRAGON_ARROW.getItemId());

		assertEquals(RangeAmmoData.OtherAmmo.SEEKING_DRAGON_ARROW, ammo);
	}

	private static PvpDamageCalc newCalc() throws Exception
	{
		Field unsafeField = Unsafe.class.getDeclaredField("theUnsafe");
		unsafeField.setAccessible(true);
		Unsafe unsafe = (Unsafe) unsafeField.get(null);
		return (PvpDamageCalc) unsafe.allocateInstance(PvpDamageCalc.class);
	}

	private static void setField(PvpDamageCalc calc, String fieldName, Object value) throws Exception
	{
		Field field = PvpDamageCalc.class.getDeclaredField(fieldName);
		field.setAccessible(true);
		field.set(calc, value);
	}
}

