package matsyir.pvpperformancetracker.controllers;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PvpHubSyncRetryStateTest
{
	@Test
	public void enqueuedFightIsDueImmediately()
	{
		PvpHubSyncRetryState retryState = new PvpHubSyncRetryState(5, 60_000);

		retryState.enqueue(" FIGHT123 ", 1_000);

		assertEquals(1, retryState.dueFightIds(1_000).size());
		assertEquals("FIGHT123", retryState.dueFightIds(1_000).get(0));
	}

	@Test
	public void failedAttemptWaitsForRetryDelay()
	{
		PvpHubSyncRetryState retryState = new PvpHubSyncRetryState(5, 60_000);
		retryState.enqueue("FIGHT123", 1_000);

		assertTrue(retryState.markAttemptStarted("FIGHT123", 1_000));
		retryState.markUnavailable("FIGHT123");

		assertTrue(retryState.dueFightIds(60_999).isEmpty());
		assertEquals("FIGHT123", retryState.dueFightIds(61_000).get(0));
	}

	@Test
	public void failedAttemptsStopAtMaxAttempts()
	{
		PvpHubSyncRetryState retryState = new PvpHubSyncRetryState(2, 60_000);
		retryState.enqueue("FIGHT123", 1_000);

		assertTrue(retryState.markAttemptStarted("FIGHT123", 1_000));
		retryState.markUnavailable("FIGHT123");
		assertFalse(retryState.isEmpty());

		assertTrue(retryState.markAttemptStarted("FIGHT123", 61_000));
		retryState.markUnavailable("FIGHT123");

		assertTrue(retryState.isEmpty());
		assertTrue(retryState.dueFightIds(121_000).isEmpty());
	}

	@Test
	public void successRemovesPendingFight()
	{
		PvpHubSyncRetryState retryState = new PvpHubSyncRetryState(5, 60_000);
		retryState.enqueue("FIGHT123", 1_000);

		retryState.remove("FIGHT123");

		assertTrue(retryState.isEmpty());
	}

	@Test
	public void clearDropsAllPendingFights()
	{
		PvpHubSyncRetryState retryState = new PvpHubSyncRetryState(5, 60_000);
		retryState.enqueue("FIGHT123", 1_000);
		retryState.enqueue("FIGHT456", 1_000);

		retryState.clear();

		assertTrue(retryState.isEmpty());
	}
}

package matsyir.pvpperformancetracker.controllers;

import matsyir.pvpperformancetracker.models.AnimationData;
import matsyir.pvpperformancetracker.models.EquipmentData;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class FighterSoulreaperStacksTest
{
	@Test
	public void mapsAndTracksSoulreaperStatePerFighter()
	{
		assertEquals(AnimationData.MELEE_SOULREAPER_AXE_CRUSH, AnimationData.fromId(10171));
		assertEquals(AnimationData.MELEE_SOULREAPER_AXE_SLASH, AnimationData.fromId(10172));
		assertEquals(AnimationData.MELEE_SOULREAPER_AXE_SPEC, AnimationData.fromId(10173));
		assertEquals(EquipmentData.SOULREAPER_AXE, EquipmentData.fromId(28338));
		assertEquals(EquipmentData.SOULREAPER_AXE, EquipmentData.fromId(33335));

		Fighter fighter = new Fighter("fighter");
		Fighter otherFighter = new Fighter("other");

		assertEquals(0, fighter.updateSoulreaperStacks(AnimationData.MELEE_SOULREAPER_AXE_CRUSH, 100));
		assertEquals(1, fighter.updateSoulreaperStacks(AnimationData.MELEE_SOULREAPER_AXE_SLASH, 105));
		assertEquals(2, fighter.updateSoulreaperStacks(AnimationData.MELEE_SOULREAPER_AXE_SLASH, 110));
		assertEquals(3, fighter.updateSoulreaperStacks(AnimationData.MELEE_SOULREAPER_AXE_SLASH, 115));
		assertEquals(4, fighter.updateSoulreaperStacks(AnimationData.MELEE_SOULREAPER_AXE_SLASH, 120));
		assertEquals(4, fighter.updateSoulreaperStacks(AnimationData.MELEE_SOULREAPER_AXE_SLASH, 170));
		assertEquals(5, fighter.updateSoulreaperStacks(AnimationData.MELEE_SOULREAPER_AXE_SPEC, 175));
		assertEquals(0, fighter.updateSoulreaperStacks(AnimationData.MELEE_SOULREAPER_AXE_SLASH, 180));

		assertEquals(0, otherFighter.updateSoulreaperStacks(AnimationData.MELEE_SOULREAPER_AXE_SLASH, 180));
	}
}

package matsyir.pvpperformancetracker.controllers;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import matsyir.pvpperformancetracker.models.AnimationData.AttackStyle;
import matsyir.pvpperformancetracker.models.CombatLevels;
import matsyir.pvpperformancetracker.models.EquipmentData;
import org.junit.Test;
import sun.misc.Unsafe;

import static org.junit.Assert.assertEquals;

public class PvpDamageCalcSoulreaperTest
{
	@Test
	public void fullStackNormalAndSpecialUseUpdatedModifiers() throws Exception
	{
		PvpDamageCalc calc = newCalc();
		Method getMeleeMaxHit = PvpDamageCalc.class.getDeclaredMethod(
			"getMeleeMaxHit",
			int.class,
			boolean.class,
			EquipmentData.class,
			EquipmentData.VoidStyle.class,
			int.class,
			int.class);
		getMeleeMaxHit.setAccessible(true);

		getMeleeMaxHit.invoke(calc, 125, false, EquipmentData.SOULREAPER_AXE, EquipmentData.VoidStyle.NONE, -1, 5);
		assertEquals(41, calc.getMaxHit());

		getMeleeMaxHit.invoke(calc, 125, true, EquipmentData.SOULREAPER_AXE, EquipmentData.VoidStyle.NONE, -1, 5);
		assertEquals(41, calc.getMaxHit());
		assertEquals(9, calc.getMinHit());

		Method getMeleeAccuracy = PvpDamageCalc.class.getDeclaredMethod(
			"getMeleeAccuracy",
			int[].class,
			int[].class,
			AttackStyle.class,
			boolean.class,
			EquipmentData.class,
			EquipmentData.VoidStyle.class,
			int.class,
			double.class,
			int.class);
		getMeleeAccuracy.setAccessible(true);

		int[] attackerStats = new int[13];
		int[] defenderStats = new int[13];
		attackerStats[1] = 100;
		defenderStats[6] = 100;

		getMeleeAccuracy.invoke(calc, attackerStats, defenderStats, AttackStyle.SLASH, true,
			EquipmentData.SOULREAPER_AXE, EquipmentData.VoidStyle.NONE, -1, 1.0, 5);
		double fullStackAccuracy = calc.getAccuracy();
		double baseAttackRoll = Math.floor((99 + 8) * (100 + 64));
		double fullStackAttackRoll = baseAttackRoll * 1.6;
		double defenderRoll = Math.floor((99 + 8) * (100 + 64));
		double expectedAccuracy = 1 - (defenderRoll + 2) / (2 * (fullStackAttackRoll + 1));
		assertEquals(expectedAccuracy, fullStackAccuracy, 0.000001);

		Method getAverageHit = PvpDamageCalc.class.getDeclaredMethod(
			"getAverageHit", boolean.class, EquipmentData.class, boolean.class);
		getAverageHit.setAccessible(true);
		getAverageHit.invoke(calc, true, EquipmentData.SOULREAPER_AXE, true);
		assertEquals(fullStackAccuracy * 25, calc.getAverageHit(), 0.000001);
	}

	private static PvpDamageCalc newCalc() throws Exception
	{
		Field unsafeField = Unsafe.class.getDeclaredField("theUnsafe");
		unsafeField.setAccessible(true);
		Unsafe unsafe = (Unsafe) unsafeField.get(null);
		PvpDamageCalc calc = (PvpDamageCalc) unsafe.allocateInstance(PvpDamageCalc.class);
		setField(calc, "attackerLevels", new CombatLevels(99, 99, 99, 99, 99, 99));
		setField(calc, "defenderLevels", new CombatLevels(99, 99, 99, 99, 99, 99));
		return calc;
	}

	private static void setField(PvpDamageCalc calc, String fieldName, Object value) throws Exception
	{
		Field field = PvpDamageCalc.class.getDeclaredField(fieldName);
		field.setAccessible(true);
		field.set(calc, value);
	}
}

package matsyir.pvpperformancetracker.controllers;

import java.util.ArrayList;
import matsyir.pvpperformancetracker.models.CombatLevels;
import matsyir.pvpperformancetracker.models.FightLogEntry;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class FighterRefreshCombatLevelsTest
{
	@Test
	public void refreshCombatLevelsForTickUpdatesOnlyMatchingTickEntriesWithLevels()
	{
		ArrayList<FightLogEntry> entries = new ArrayList<>();
		int[] attackerGear = {1, 2, 3};
		int[] defenderGear = {4, 5, 6};

		FightLogEntry previousTickEntry = new FightLogEntry(attackerGear, 21, 0.5, 1, 12, defenderGear, "competitor", 103, 1000L);
		previousTickEntry.setAttackerLevels(new CombatLevels(99, 99, 99, 99, 90, 99));

		FightLogEntry targetTickEntry = new FightLogEntry(attackerGear, 21, 0.5, 1, 12, defenderGear, "competitor", 104, 1200L);
		targetTickEntry.setAttackerLevels(new CombatLevels(99, 99, 99, 99, 90, 99));

		FightLogEntry targetTickWithoutLevels = new FightLogEntry(attackerGear, 21, 0.5, 1, 12, defenderGear, "competitor", 104, 1300L);

		entries.add(previousTickEntry);
		entries.add(targetTickEntry);
		entries.add(targetTickWithoutLevels);

		Fighter.refreshCombatLevelsForTick(entries, 104, new CombatLevels(99, 99, 99, 99, 99, 99));

		assertEquals(90, previousTickEntry.getAttackerLevels().mage);
		assertEquals(99, targetTickEntry.getAttackerLevels().mage);
		assertNull(targetTickWithoutLevels.getAttackerLevels());
	}
}

