	public boolean isActive(Client client)
	{
		return isPrayerActive(client, prayer) && isEnabled(client);
	}

	boolean isEnabled(Client client)
	{
		return true;
	}
	private static boolean isPrayerActive(Client client, Prayer prayer)
	{
		return client.getVarbitValue(prayer.getVarbit()) == 1;
	}
}

