	BRIMSTONE_RING("Brimstone Ring", ItemID.BRIMSTONE_RING),
	MAGUS_RING("Magus ring", ItemID.MAGUS_RING_28313),
	VENATOR_RING("Venator ring", ItemID.VENATOR_RING_28310),
