import lombok.Getter;
import org.apache.commons.lang3.StringUtils;

public interface RangeAmmoData
{
	int SEEKING_ARROW_ACCURACY_BONUS = 20;
	int SEEKING_ARROW_MIN_HIT = 3;

	RangeAmmoData[] DIAMOND_BOLTS = {
		BoltAmmo.DIAMOND_BOLTS_E,
		StrongBoltAmmo.DIAMOND_BOLTS_E,
		StrongBoltAmmo.DIAMOND_DRAGON_BOLTS_E
	};

	RangeAmmoData[] OPAL_BOLTS = {
		StrongBoltAmmo.OPAL_DRAGON_BOLTS_E
	};

	RangeAmmoData[] SEEKING_ARROW_AMMO = {
		OtherAmmo.SEEKING_BRONZE_ARROW,
		OtherAmmo.SEEKING_IRON_ARROW,
		OtherAmmo.SEEKING_STEEL_ARROW,
		OtherAmmo.SEEKING_MITHRIL_ARROW,
		OtherAmmo.SEEKING_ADAMANT_ARROW,
		OtherAmmo.SEEKING_RUNE_ARROW,
		OtherAmmo.SEEKING_AMETHYST_ARROW,
		OtherAmmo.SEEKING_DRAGON_ARROW,
		OtherAmmo.SEEKING_BROAD_ARROWS
	};

	static RangeAmmoData fromId(int itemId)
	{
		for (BoltAmmo ammo : BoltAmmo.values())
		{
			if (ammo.getItemId() == itemId)
			{
				return ammo;
			}
		}
		for (StrongBoltAmmo ammo : StrongBoltAmmo.values())
		{
			if (ammo.getItemId() == itemId)
			{
				return ammo;
			}
		}
		for (DartAmmo ammo : DartAmmo.values())
		{
			if (ammo.getItemId() == itemId)
			{
				return ammo;
			}
		}
		for (OtherAmmo ammo : OtherAmmo.values())
		{
			if (ammo.getItemId() == itemId)
			{
				return ammo;
			}
		}
		return null;
	}

	static boolean usesSeekingArrowUpgrade(RangeAmmoData ammo, boolean isLmsFight)
	{
		return !isLmsFight && Arrays.stream(SEEKING_ARROW_AMMO).anyMatch(seekingArrowAmmo -> seekingArrowAmmo == ammo);
	}

	static int getSeekingArrowAccuracyBonus(RangeAmmoData ammo, boolean isLmsFight)
	{
		return usesSeekingArrowUpgrade(ammo, isLmsFight) ? SEEKING_ARROW_ACCURACY_BONUS : 0;
	}

	static int getSeekingArrowMinimumHit(RangeAmmoData ammo, boolean isLmsFight)
	{
		return usesSeekingArrowUpgrade(ammo, isLmsFight) ? SEEKING_ARROW_MIN_HIT : 0;
	}

	int getItemId(); // itemIDs used for DISPLAYING bolts, not getting them.
	int getRangeStr();
	double getBonusMaxHit(int rangeLevel); // damage bonus from bolt specs.
	double getDmgModifier(); // damage modifier from bolt specs.

	interface RangeAmmoConfigData extends RangeAmmoData
	{
		String getName();
	}

	@Getter
	enum BoltAmmo implements RangeAmmoConfigData
	{
		RUNITE_BOLTS("Runite Bolts", 9169, 115, 1),
		DRAGONSTONE_BOLTS_E("Dstone Bolts (e)", 9244, 117, 1, .2, 0.06),
		DIAMOND_BOLTS_E("Diamond Bolts (e)", 9243, 105, 1.015);

		static EquipmentData[] WEAPONS_USING = { EquipmentData.RUNE_CROSSBOW };

		private String name;
		private int itemId;
		private int rangeStr;
		private double specRangeLevelModifier;
		private double specChance;
		private double dmgModifier;

		BoltAmmo(String name, int itemId, int rangeStr, double dmgModifier, double specRangeLevelModifier, double specChance)
		{
			this.name = name;
			this.itemId = itemId;
			this.rangeStr = rangeStr;
			this.specRangeLevelModifier = specRangeLevelModifier;
			this.specChance = specChance;
			this.dmgModifier = dmgModifier;
		}
		BoltAmmo(String name, int itemId, int rangeStr, double dmgModifier)
		{
			this.name = name;
			this.itemId = itemId;
			this.rangeStr = rangeStr;
			this.specRangeLevelModifier = 0;
			this.specChance = 0;
			this.dmgModifier = dmgModifier;
		}

		public double getBonusMaxHit(int rangeLevel)
		{
			return rangeLevel * specRangeLevelModifier * specChance;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	@Getter
	enum StrongBoltAmmo implements RangeAmmoConfigData
	{
		RUNITE_BOLTS("<html><font color='#ff0000'>&#9888;</font> runite bolts", 9169, 115, 1),
		DRAGONSTONE_BOLTS_E("<html><font color='#ff0000'>&#9888;</font> dstone bolts (e)", 9244, 117, 1, .2, 0.06),
		DIAMOND_BOLTS_E("<html><font color='#ff0000'>&#9888;</font> diamond bolts (e)", 9243, 105, 1.015),
		DRAGONSTONE_DRAGON_BOLTS_E("<html>Dstone <u>D-Bolts</u> (e)", 21948, 122, 1, .2, .06),
		OPAL_DRAGON_BOLTS_E("<html>Opal <u>D-Bolts</u> (e)", 21932, 122, 1, .1, .05),
		DIAMOND_DRAGON_BOLTS_E("<html>Diamond <u>D-Bolts</u> (e)", 21946, 122, 1.015);

		static EquipmentData[] WEAPONS_USING = {
			EquipmentData.ARMADYL_CROSSBOW,
			EquipmentData.DRAGON_CROSSBOW,
			EquipmentData.DRAGON_HUNTER_CROSSBOW,
			EquipmentData.ZARYTE_CROSSBOW
		};

		private String name;
		private int rangeStr;
		private int itemId;
		private double specRangeLevelModifier;
		private double specChance;
		private double dmgModifier;

		StrongBoltAmmo(String name, int itemId, int rangeStr, double dmgModifier, double specRangeLevelModifier, double specChance)
		{
			this.name = name;
			this.itemId = itemId;
			this.rangeStr = rangeStr;
			this.specRangeLevelModifier = specRangeLevelModifier;
			this.specChance = specChance;
			this.dmgModifier = dmgModifier;
		}
		StrongBoltAmmo(String name, int itemId, int rangeStr, double dmgModifier)
		{
			this.name = name;
			this.itemId = itemId;
			this.rangeStr = rangeStr;
			this.specRangeLevelModifier = 0;
			this.specChance = 0;
			this.dmgModifier = dmgModifier;
		}

		public double getBonusMaxHit(int rangeLevel)
		{
			return rangeLevel * specRangeLevelModifier * specChance;
		}


		@Override
		public String toString()
		{
			return name;
		}
	}

	@Getter
	public enum DartAmmo implements RangeAmmoConfigData
	{
		ADAMANT_DARTS("Adamant Darts", 810, 10),
		RUNE_DARTS("Rune Darts", 811, 14),
		DRAGON_DARTS("Dragon Darts", 11230, 20);

		static EquipmentData[] WEAPONS_USING = { EquipmentData.TOXIC_BLOWPIPE };

		private String name;
		private int itemId;
		private int rangeStr;
		private double bonusMaxHit;
		private double dmgModifier;

		DartAmmo(String name, int itemId, int rangeStr)
		{
			this.name = name;
			this.itemId = itemId;
			this.rangeStr = rangeStr;
			this.bonusMaxHit = 0;
			this.dmgModifier = 1;
		}

		public double getBonusMaxHit(int rangeLevel)
		{
			return 0;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	@Getter
	public enum OtherAmmo implements RangeAmmoData
	{
		AMETHYST_ARROWS(21326, 55),
		DRAGON_ARROW(11212, 60),
		SEEKING_BRONZE_ARROW(33553, 7),
		SEEKING_IRON_ARROW(33559, 10),
		SEEKING_STEEL_ARROW(33565, 16),
		SEEKING_MITHRIL_ARROW(33571, 22),
		SEEKING_ADAMANT_ARROW(33577, 31),
		SEEKING_RUNE_ARROW(33583, 49),
		SEEKING_AMETHYST_ARROW(33589, 55),
		SEEKING_DRAGON_ARROW(33595, 60),
		SEEKING_BROAD_ARROWS(33601, 28),
		DRAGON_JAVELIN(19484, 150),
		BOLT_RACK(4740, 55),
		MOONLIGHT_ANTLER_BOLTS(28878, 60);

		private int rangeStr;
		private int itemId;
		private double bonusMaxHit;
		private double dmgModifier;

		OtherAmmo(int itemId, int rangeStr)
		{
			this.itemId = itemId;
			this.rangeStr = rangeStr;
			this.bonusMaxHit = 0;
			this.dmgModifier = 1;
		}

		public double getBonusMaxHit(int rangeLevel)
		{
			return 0;
		}

		@Override
		public String toString()
		{
			String[] words = super.toString().toLowerCase().split("_");
			Arrays.stream(words)
				.map(StringUtils::capitalize).collect(Collectors.toList()).toArray(words);

			return String.join(" ", words);
		}
	}
