		defenderAtkLvl = new JLabel();
		PLUGIN.addSpriteToLabelIfValid(defenderAtkLvl, PvpUtils.getSpriteForSkill(Skill.ATTACK));
		defenderAtkLvl.setText(String.valueOf(defLevels.atk));
